'use strict';
const $=(s,root=document)=>root.querySelector(s), $$=(s,root=document)=>[...root.querySelectorAll(s)];
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const money=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(value);
const sizes=['S · EU 36–39','M · EU 40–43'];
const products=[{"id":"signature","name":"Minimal Icon","en":"N x S x E / 01","price":18,"category":"daily","color":"Ivory / Olive","dots":["#e8e3d7","#474d35"],"image":"signature","tag":"NEW / 01","description":"Our new signature joins molecular geometry with mountain peaks and a rising sun. Fine dark-olive embroidery on an ivory ribbed crew, finished with olive heels and toes. A small mark with a new perspective.","keywords":"minimal cream ivory olive embroidery logo sunrise sun mountain new signature","crop":[0,280,143,329],"sizes":["S · EU 36–39","M · EU 40–43"]},{"id":"backtab","name":"Back Tab","en":"N x S x E / 02","price":18,"category":"daily","color":"Olive","dots":["#454b35"],"image":"backtab","tag":"NO. 02","description":"Deep olive ribbing, finished with a small black woven tab at the back cuff. A subtle mark you discover on a second look.","keywords":"green olive black tab back label","crop":[149,280,145,329],"sizes":["S · EU 36–39","M · EU 40–43"]},{"id":"vertical","name":"Vertical Line","en":"N x S x E / 03","price":22,"category":"statement","color":"Black / Ecru","dots":["#181919","#d8ceb5"],"image":"vertical","tag":"NO. 03","description":"A fine vertical molecular line runs along a black crew. Precise, graphic and quietly expressive.","keywords":"black vertical line molecule cream","crop":[306,280,148,329],"sizes":["S · EU 36–39","M · EU 40–43"]},{"id":"half","name":"Half Pattern","en":"N x S x E / 04","price":22,"category":"statement","color":"Ivory / Sand","dots":["#e4decd","#b5a88d"],"image":"half","tag":"NO. 04","description":"A soft tonal molecular pattern traces one side of ivory knit. Detail that comes into view with every step.","keywords":"cream ivory half pattern tonal sand","crop":[465,280,147,329],"sizes":["S · EU 36–39","M · EU 40–43"]},{"id":"heather","name":"Heather Blend","en":"N x S x E / 05","price":20,"category":"daily","color":"Heather Grey","dots":["#777a69"],"image":"heather","tag":"NO. 05","description":"Mottled grey and olive yarns bring texture to a familiar shape. Finished with a small ecru molecular emblem.","keywords":"grey gray heather blend olive","crop":[620,280,145,329],"sizes":["S · EU 36–39","M · EU 40–43"]},{"id":"twotone","name":"Two Tone","en":"N x S x E / 06","price":20,"category":"daily","color":"Ivory / Olive","dots":["#e5dfd0","#454b33"],"image":"twotone","tag":"NO. 06","description":"An ivory body framed by an olive cuff, heel and toe. A small dark molecular signature completes the contrast.","keywords":"cream ivory olive two tone cuff","crop":[777,280,145,329],"sizes":["S · EU 36–39","M · EU 40–43"]},{"id":"allover","name":"All Over Mini","en":"N x S x E / 07","price":24,"category":"statement","color":"Black / Sand","dots":["#151515","#b6a891"],"image":"allover","tag":"NO. 07","description":"Miniature molecular marks scattered across black ribbing. An all-over pattern with a deliberately restrained scale.","keywords":"black all over mini pattern sand","crop":[936,280,140,329],"sizes":["S · EU 36–39","M · EU 40–43"]},{"id":"side","name":"Side Stripe","en":"N x S x E / 08","price":22,"category":"statement","color":"Olive / Ecru","dots":["#434832","#dcd5c0"],"image":"side","tag":"NO. 08","description":"One fine ecru line and an open molecular motif on deep olive. A clean, lengthened silhouette.","keywords":"olive green side stripe line","crop":[1091,280,140,329],"sizes":["S · EU 36–39","M · EU 40–43"]},{"id":"block","name":"Block Logo","en":"N x S x E / 09","price":22,"category":"statement","color":"Ivory / Black","dots":["#e8e2d6","#181918"],"image":"block","tag":"NO. 09","description":"A black band interrupts ivory ribbing, framing a fine ecru molecular emblem. Graphic contrast, carefully balanced.","keywords":"ivory cream black block logo band","crop":[1248,280,136,329],"sizes":["S · EU 36–39","M · EU 40–43"]},{"id":"tonal","name":"Tonal Pattern","en":"N x S x E / 10","price":24,"category":"statement","color":"Black / Charcoal","dots":["#181818","#45463f"],"image":"tonal","tag":"NO. 10","description":"Charcoal molecular lines blend into black knit. A patterned crew that reveals its detail as the light changes.","keywords":"black charcoal tonal pattern dark","crop":[1401,280,134,329],"sizes":["S · EU 36–39","M · EU 40–43"]},{"id":"gift","name":"The Collection Set","en":"N x S x E / SET","price":88,"category":"gift","color":"Five considered pairs","dots":["#414733","#e5dfd2","#171717"],"image":"gift","tag":"FIVE PAIRS","description":"Five expressions of N x S x E, curated as one set: olive, ivory, ivory pattern, black pattern and heather. A gift with a point of view.","keywords":"gift set five pairs box present collection","crop":[651,729,341,291],"sizes":["S · EU 36–39","M · EU 40–43"]}];
const findProduct=id=>products.find(p=>p.id===id);
function readStorage(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback;}catch{return fallback;}}
const storedCart=readStorage('sole-cart',[]);
let cart=Array.isArray(storedCart)?storedCart.filter(x=>x&&findProduct(x.id)&&sizes.includes(x.size)&&Number.isInteger(x.qty)&&x.qty>0).map(x=>({id:x.id,size:x.size,qty:Math.min(x.qty,20)})):[];
const storedFavorites=readStorage('sole-favorites',[]);
let favorites=new Set(Array.isArray(storedFavorites)?storedFavorites.filter(x=>findProduct(x)):[]);
let currentFilter='all',selectedProduct=null,selectedSize='',selectedQty=1,quickProduct=findProduct('signature'),quickSize='',quickQty=1,toastTimer;
function persist(){try{localStorage.setItem('sole-cart',JSON.stringify(cart));localStorage.setItem('sole-favorites',JSON.stringify([...favorites]));}catch{}}
function productImage(p,extra=''){if(p.id==='signature')return `<img class="product-image minimal-image ${extra}" src="assets/nse-minimal.jpg" alt="${p.name} — ${p.color}" loading="lazy">`;const[x,y,w,h]=p.crop;return `<span class="product-image board-image ${extra}" role="img" aria-label="${p.name} — ${p.color}"><span class="board-crop" style="aspect-ratio:${w}/${h}"><img src="assets/botanic-board.jpg" alt="" loading="lazy" style="width:${1536/w*100}%;height:${1024/h*100}%;left:${-x/w*100}%;top:${-y/h*100}%"></span></span>`;}

function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function openDialog(id){const d=$('#'+id);if(!d.open)d.showModal();}
function updateHeader(){const count=cart.reduce((n,x)=>n+x.qty,0);$('.cart-count').textContent=count;$('.bag-trigger').setAttribute('aria-label',`Shopping bag, ${count} items`);$('.wishlist-dot').hidden=favorites.size===0;$('#drawer-count').textContent=count;}
function renderProducts(){const shown=currentFilter==='all'?products.filter(p=>p.category!=='gift'):currentFilter==='wishlist'?products.filter(p=>favorites.has(p.id)):products.filter(p=>p.category===currentFilter);$('#product-grid').innerHTML=shown.map(p=>`<article class="product-card"><div class="product-image-wrap"><button class="product-open" data-product="${p.id}" aria-label="View ${p.name}">${productImage(p)}</button><span class="product-tag">${p.tag}</span><button class="favorite-button" data-favorite="${p.id}" aria-label="Save ${p.name} to wishlist" aria-pressed="${favorites.has(p.id)}">${icon('heart')}</button><button class="quick-add" data-product="${p.id}" aria-label="Choose a size for ${p.name}">${icon('plus')}</button></div><p class="product-category">${p.en}</p><div class="product-title-row"><button class="product-name" data-product="${p.id}">${p.name}</button><p class="product-price">${money(p.price)}</p></div><div class="product-color">${p.dots.map(color=>`<span class="color-dot" style="--dot:${color}" aria-hidden="true"></span>`).join('')}<span>${p.color}</span></div></article>`).join('');$('#result-count').textContent=`${shown.length} STYLES`;$('#catalog-empty').hidden=shown.length>0;$$('[data-filter]').forEach(b=>{const active=b.dataset.filter===currentFilter;b.classList.toggle('active',active);b.setAttribute('aria-pressed',active);});$('.wishlist-filter').hidden=currentFilter!=='wishlist';}
function setFilter(filter){currentFilter=filter;renderProducts();}
function openProduct(id){const p=findProduct(id);if(!p)return;selectedProduct=p;selectedSize='';selectedQty=1;$('#product-detail').innerHTML=`<div class="detail-layout"><div class="detail-photo">${productImage(p)}</div><div class="detail-copy"><p class="eyebrow">${p.en}</p><h2 id="product-dialog-title">${p.name}</h2><p class="detail-price">${money(p.price)}</p><p class="detail-description">${p.description}</p><p class="detail-meta"><span>COLOR</span>${p.color}</p><div class="size-heading"><span>SIZE</span><button data-action="size-guide">Size guide ↗</button></div><div class="size-options" role="group" aria-label="Choose a size" aria-describedby="size-error">${sizes.map(size=>`<button class="size-option" data-size="${size}" aria-pressed="false">${size}</button>`).join('')}</div><p class="size-error" id="size-error" role="alert"></p><div class="detail-bottom"><div class="quantity-control" aria-label="Quantity"><button data-detail-qty="-1" aria-label="Decrease quantity" disabled>${icon('minus')}</button><output id="detail-qty" aria-live="polite">1</output><button data-detail-qty="1" aria-label="Increase quantity">${icon('plus')}</button></div><button class="button button-burgundy" data-action="add-to-cart">ADD TO BAG ${icon('bag')}</button></div><p class="detail-care">Complimentary shipping on $50+ · Otherwise $5<br>Concept product. No actual payment or order.</p></div></div>`;openDialog('product-dialog');}
function addItem(p,size,qty,errorNode){if(!size){errorNode.textContent='Please select a size.';return false;}const found=cart.find(x=>x.id===p.id&&x.size===size);if(found&&found.qty+qty>20){errorNode.textContent='You can add up to 20 of each size.';return false;}if(found)found.qty+=qty;else cart.push({id:p.id,size,qty});persist();updateHeader();errorNode.textContent='';return true;}
function addToCart(){if(!selectedProduct)return;if(addItem(selectedProduct,selectedSize,selectedQty,$('#size-error'))){$('#product-dialog').close();renderCart();openDialog('cart-dialog');}else if(!selectedSize)$('.size-option').focus();}
function updateQuick(){const p=quickProduct;$('#quick-product-name').textContent=p.name;$('#quick-color-name').textContent=p.color.toUpperCase();$('.quick-intro').textContent='Inspired by nature. Made for every day.';$('#quick-price').textContent=money(p.price*quickQty);$('#stage-category').textContent=p.name.toUpperCase();$('#stage-price').textContent=money(p.price);$('#stage-image').innerHTML=productImage(p);$('#stage-details').dataset.product=p.id;$$('[data-quick-product]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.quickProduct===p.id));$('#quick-qty').textContent=quickQty;$('[data-quick-qty="-1"]').disabled=quickQty===1;$('[data-quick-qty="1"]').disabled=quickQty===20;}
function cartTotals(){const subtotal=cart.reduce((sum,x)=>sum+findProduct(x.id).price*x.qty,0);const shipping=subtotal===0||subtotal>=50?0:5;return{subtotal,shipping,total:subtotal+shipping};}
function renderCart(){updateHeader();if(!cart.length){$('#cart-content').innerHTML=`<div class="empty-state cart-empty">${icon('bag')}<h3>A little room for something good.</h3><p>Your bag is empty.<br>Find a pair that feels like you.</p><button class="button button-dark" data-action="continue-shopping">EXPLORE THE COLLECTION ${icon('arrow')}</button></div>`;return;}const{subtotal,shipping,total}=cartTotals();$('#cart-content').innerHTML=`<div class="cart-items">${cart.map((x,i)=>{const p=findProduct(x.id);return `<article class="cart-item">${productImage(p,'cart-thumb')}<div class="cart-item-info"><h3>${p.name}</h3><button class="cart-remove" data-cart-remove="${i}" aria-label="Remove ${p.name}">${icon('close')}</button><p class="cart-item-description">${p.color} · ${x.size}</p><p class="cart-item-price">${money(p.price*x.qty)}</p><div class="quantity-control"><button data-cart-qty="${i}" data-delta="-1" aria-label="Decrease ${p.name} quantity" ${x.qty===1?'disabled':''}>${icon('minus')}</button><output aria-label="Quantity">${x.qty}</output><button data-cart-qty="${i}" data-delta="1" aria-label="Increase ${p.name} quantity" ${x.qty===20?'disabled':''}>${icon('plus')}</button></div></div></article>`;}).join('')}</div><div class="cart-summary"><p class="shipping-hint">${subtotal>=50?'Your order qualifies for complimentary shipping.':`You’re ${money(50-subtotal)} away from complimentary shipping.`}</p><div class="shipping-progress" aria-hidden="true"><span style="width:${Math.min(100,subtotal/50*100)}%"></span></div><div class="summary-line"><span>Subtotal</span><span>${money(subtotal)}</span></div><div class="summary-line"><span>Shipping</span><span>${shipping===0?'Complimentary':money(shipping)}</span></div><div class="summary-line total"><span>Total</span><span>${money(total)}</span></div><button class="button button-burgundy" data-action="review-order">REVIEW YOUR ORDER ${icon('arrow')}</button><p class="demo-note">Concept store. No payment will be taken.</p></div>`;}
function renderSearch(){const q=$('#search-input').value.trim().toLowerCase(),matched=products.filter(p=>`${p.name} ${p.en} ${p.keywords}`.toLowerCase().includes(q));$('#search-status').textContent=q?`${matched.length} ${matched.length===1?'piece':'pieces'} found`:'Explore the complete collection.';$('#search-results').innerHTML=matched.length?matched.map(p=>`<button class="search-result" data-search-product="${p.id}">${productImage(p)}<span><span class="search-result-title">${p.name}</span><span class="search-result-meta">${money(p.price)} · ${p.color}</span></span>${icon('arrow')}</button>`).join(''):`<div class="empty-state"><h3>No pieces found.</h3><p>Try a color, a style or a shorter search.</p><button class="text-link" data-action="reset-search">VIEW ALL PIECES ↗</button></div>`;}
const infoContent={
'size-guide':`<p class="eyebrow">FIND YOUR FIT</p><h2 id="info-title">A considered fit.</h2><p>Choose your usual shoe size. If you fall between sizes, choose the larger size for a more relaxed fit.</p><table><thead><tr><th scope="col">Size</th><th scope="col">Foot length</th><th scope="col">EU shoe size</th></tr></thead><tbody><tr><td>S</td><td>230–250 mm</td><td>36–39</td></tr><tr><td>M</td><td>250–275 mm</td><td>40–43</td></tr></tbody></table><p>All styles are unisex. This is an illustrative size guide for concept products, not verified production measurements.</p>`,
care:`<p class="eyebrow">KEEP THE GOOD THINGS</p><h2 id="info-title">A little care goes a long way.</h2><ul><li>Turn inside out and use a laundry bag.</li><li>Wash with similar colors at 30°C or below.</li><li>Use a mild detergent.</li><li>Avoid bleach and tumble drying.</li><li>Air-dry away from direct sunlight.</li></ul><p>Always follow the care label supplied with an actual product.</p>`,
delivery:`<p class="eyebrow">CLIENT SERVICES</p><h2 id="info-title">Shipping & returns.</h2><p>This is a concept store. No orders, shipments or returns are processed.</p><table><tbody><tr><th scope="row">Illustrative shipping</th><td>$5.00</td></tr><tr><th scope="row">Complimentary shipping</th><td>Orders of $50 or more</td></tr><tr><th scope="row">Fulfilment</th><td>Not connected</td></tr></tbody></table><p>Delivery times and return terms will be available before the store opens for actual purchases.</p>`,
privacy:`<p class="eyebrow">YOUR PRIVACY</p><h2 id="info-title">Thoughtful by design.</h2><p>This concept store does not request or send your name, address, phone number or payment details.</p><p>Your bag and wishlist are stored only in this browser. Clearing browser data removes them. Search terms are not sent to a server.</p><p>Site authentication is managed by the hosting service. Fonts are served by Google Fonts, which receives normal connection information when the page loads.</p><button class="button button-outline" data-action="clear-local">RESET BAG & WISHLIST</button>`
};
function showInfo(type){$('#info-content').innerHTML=infoContent[type]||infoContent['size-guide'];openDialog('info-dialog');}
function reviewOrder(){const{subtotal,shipping,total}=cartTotals();$('#info-content').innerHTML=`<p class="eyebrow">YOUR SELECTION</p><h2 id="info-title">Good choices. All here.</h2><p>Review your selection below.</p>${cart.map(x=>`<div class="order-review-line"><div>${findProduct(x.id).name}<br><span>${x.size} · Qty ${x.qty}</span></div><div>${money(findProduct(x.id).price*x.qty)}</div></div>`).join('')}<div class="summary-line"><span>Subtotal</span><span>${money(subtotal)}</span></div><div class="summary-line"><span>Shipping</span><span>${shipping?money(shipping):'Complimentary'}</span></div><div class="summary-line total"><span>Estimated total</span><span>${money(total)}</span></div><p><strong>No order has been placed.</strong><br>This concept store is not connected to a payment service. Your selection remains in your bag.</p><button class="button button-dark" data-close>BACK TO YOUR BAG ${icon('arrow')}</button>`;openDialog('info-dialog');}
function closeMobileMenu(){$('.mobile-nav').hidden=true;$('.mobile-menu').setAttribute('aria-expanded','false');}
document.addEventListener('click',event=>{const b=event.target.closest('button,a');if(!b)return;
if(b.hasAttribute('data-close')){b.closest('dialog').close();return;}
if(b.dataset.product){openProduct(b.dataset.product);return;}
if(b.dataset.searchProduct){$('#search-dialog').close();openProduct(b.dataset.searchProduct);return;}
if(b.dataset.favorite){const id=b.dataset.favorite;favorites.has(id)?favorites.delete(id):favorites.add(id);persist();updateHeader();if(currentFilter==='wishlist')renderProducts();else b.setAttribute('aria-pressed',favorites.has(id));toast(favorites.has(id)?'Saved to your wishlist.':'Removed from your wishlist.');return;}
if(b.dataset.filter){setFilter(b.dataset.filter);return;}
if(b.dataset.navFilter){setFilter(b.dataset.navFilter);closeMobileMenu();return;}
if(b.dataset.size){selectedSize=b.dataset.size;$$('.size-option').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b);});$('#size-error').textContent='';return;}
if(b.dataset.detailQty){selectedQty=Math.max(1,Math.min(20,selectedQty+Number(b.dataset.detailQty)));$('#detail-qty').textContent=selectedQty;$('[data-detail-qty="-1"]').disabled=selectedQty===1;$('[data-detail-qty="1"]').disabled=selectedQty===20;return;}
if(b.dataset.quickProduct){quickProduct=findProduct(b.dataset.quickProduct);updateQuick();return;}
if(b.dataset.quickSize){quickSize=b.dataset.quickSize;$$('[data-quick-size]').forEach(x=>x.setAttribute('aria-pressed',x===b));$('#quick-error').textContent='';return;}
if(b.dataset.quickQty){quickQty=Math.max(1,Math.min(20,quickQty+Number(b.dataset.quickQty)));updateQuick();return;}
if(b.dataset.cartRemove!==undefined){cart.splice(Number(b.dataset.cartRemove),1);persist();renderCart();toast('Removed from your bag.');return;}
if(b.dataset.cartQty!==undefined){const i=Number(b.dataset.cartQty);cart[i].qty=Math.max(1,Math.min(20,cart[i].qty+Number(b.dataset.delta)));persist();renderCart();const next=$(`[data-cart-qty="${i}"][data-delta="${b.dataset.delta}"]`);if(next&&!next.disabled)next.focus();return;}
if(b.dataset.info){showInfo(b.dataset.info);return;}
switch(b.dataset.action){case'cart':renderCart();openDialog('cart-dialog');break;case'search':$('#search-input').value='';renderSearch();openDialog('search-dialog');$('#search-input').focus();break;case'reset-search':$('#search-input').value='';renderSearch();$('#search-input').focus();break;case'wishlist':setFilter('wishlist');closeMobileMenu();$('#collection').scrollIntoView();break;case'size-guide':showInfo('size-guide');break;case'add-to-cart':addToCart();break;case'quick-add':if(addItem(quickProduct,quickSize,quickQty,$('#quick-error'))){renderCart();openDialog('cart-dialog');}else if(!quickSize)$('[data-quick-size]').focus();break;case'continue-shopping':$('#cart-dialog').close();setFilter('all');$('#collection').scrollIntoView();break;case'review-order':reviewOrder();break;case'menu':{const nav=$('.mobile-nav');nav.hidden=!nav.hidden;b.setAttribute('aria-expanded',!nav.hidden);break;}case'clear-local':cart=[];favorites.clear();persist();updateHeader();renderProducts();if($('#cart-dialog').open)renderCart();$('#info-dialog').close();toast('Your bag and wishlist have been reset.');break;}
if(b.closest('.mobile-nav'))closeMobileMenu();});
$('#search-input').addEventListener('input',renderSearch);
$$('dialog').forEach(d=>d.addEventListener('click',event=>{if(event.target===d){const r=d.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)d.close();}}));
renderProducts();updateHeader();updateQuick();
